 # LINQ chains in extension/hot-path files (.Select, .Where, .Cast, .Take, .Aggregate)
 grep -rn --include='*.cs' -E '\.(Select|Where|Cast|Take|Aggregate)\(' --exclude-dir=bin --exclude-dir=obj . | wc -l
